import matplotlib.pyplot as plt
import numpy as np

def plot_constellation(symbols, title="Сигнальное созвездие"):
    """
    Отрисовывает созвездие по массиву комплексных отсчетов.
    """
    # Создаем фигуру
    plt.figure(figsize=(7, 7))
    
    # Разделяем на I и Q компоненты
    i_coords = np.real(symbols)
    q_coords = np.imag(symbols)
    
    # Рисуем точки
    plt.scatter(i_coords, q_coords, color='blue', marker='o', s=30, alpha=0.6)
    
    # Добавляем оси и сетку
    plt.axhline(0, color='black', linewidth=1)
    plt.axvline(0, color='black', linewidth=1)
    plt.grid(True, linestyle='--', alpha=0.5)
    
    # Настраиваем заголовки
    plt.title(title)
    plt.xlabel('In-Phase (I)')
    plt.ylabel('Quadrature (Q)')
    
    # Выравниваем масштаб осей, чтобы круг не выглядел как овал
    limit = max(max(abs(i_coords)), max(abs(q_coords))) * 1.2
    plt.xlim(-limit, limit)
    plt.ylim(-limit, limit)
    
    plt.show()

